// Get all items
const items = $input.all();
const results = [];

for (const item of items) {
  // Get binary data
  const binaryData = item.binary;

  if (!binaryData || Object.keys(binaryData).length === 0) {
    throw new Error('No binary data received in upload');
  }

  // Get the first binary property key (uploaded file)
  const binaryKey = Object.keys(binaryData)[0];
  const fileData = binaryData[binaryKey];

  // Extract metadata
  const originalFilename = fileData.fileName || binaryKey || 'unknown';
  const extension = originalFilename.split('.').pop() || 'bin';
  const timestamp = Date.now();
  const newFilename = `${timestamp}_${originalFilename}`;

  // Calculate file size in bytes
  let fileSizeBytes = 0;
  if (fileData.data) {
    fileSizeBytes = Buffer.from(fileData.data, 'base64').length;
  }

  // Build result with BOTH json and binary
  results.push({
    json: {
      timestamp: timestamp,
      binary_key: binaryKey,
      original_filename: originalFilename,
      new_filename: newFilename,
      file_extension: extension,
      file_path: `/data/uploads/${newFilename}`,
      file_size_bytes: fileSizeBytes,
      mime_type: fileData.mimeType || 'application/octet-stream',
      upload_timestamp: new Date().toISOString()
    },
    binary: {
      file: fileData  // IMPORTANT: Keep binary data with key 'file'
    }
  });
}

return results;

